arguments.cmd:
python3 - <<'EOF'
import os
for root,dirs,files in os.walk('/challenge/inhere'):
    for f in files:
        p=os.path.join(root,f)
        try:
            xa=os.listxattr(p)
            if xa: print(p, xa, [os.getxattr(p,a) for a in xa])
        except Exception as e: print('err',p,e)
print('xattr scan done')
EOF
grep -v 'cgroup\|proc\|sys\|dev' /proc/mounts

